package com.axsos.Life.models; import jakarta.persistence.*;
@Entity @Table(name="meal_circle_members",uniqueConstraints=@UniqueConstraint(columnNames={"session_id","user_id"})) public class MealCircleMember extends BaseEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="session_id") private MealCircleSession session; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; private String foodPreference; private String personalizedMealTitle; @Column(length=2000) private String personalizedMealDescription; private Integer kcal; private Double protein; private Double carbs; private Double fat; @Column(length=2000) private String aiExplanation;
 public Long getId(){return id;} public void setId(Long v){id=v;} public MealCircleSession getSession(){return session;} public void setSession(MealCircleSession v){session=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getFoodPreference(){return foodPreference;} public void setFoodPreference(String v){foodPreference=v;} public String getPersonalizedMealTitle(){return personalizedMealTitle;} public void setPersonalizedMealTitle(String v){personalizedMealTitle=v;} public String getPersonalizedMealDescription(){return personalizedMealDescription;} public void setPersonalizedMealDescription(String v){personalizedMealDescription=v;} public Integer getKcal(){return kcal;} public void setKcal(Integer v){kcal=v;} public Double getProtein(){return protein;} public void setProtein(Double v){protein=v;} public Double getCarbs(){return carbs;} public void setCarbs(Double v){carbs=v;} public Double getFat(){return fat;} public void setFat(Double v){fat=v;} public String getAiExplanation(){return aiExplanation;} public void setAiExplanation(String v){aiExplanation=v;}
}
